// DEEP: Understands polymorphism and when to apply it
public interface PaymentMethod {
    PaymentResult process(BigDecimal amount);
}

public record CardPayment(String cardNumber) implements PaymentMethod {
    @Override
    public PaymentResult process(BigDecimal amount) {
        // Card-specific logic isolated here
        return new PaymentResult(true, "Card processed");
    }
}

public class PaymentService {
    // Open-closed principle: extend with new payment types
    // without modifying this method
    public PaymentResult processPayment(PaymentMethod method, BigDecimal amount) {
        return method.process(amount); // Polymorphism in action
    }
}
